<script setup lang="ts">
import {uiLabel} from '../ui-label'
import {entryDisplayName as localizedEntryName} from '../runtime-presentation'

import { i18n as controlI18n } from '../../app/i18n'
const { t: controlText } = controlI18n.global

import MapFieldPicker from "../map-selection/MapFieldPicker.vue"
import MapPositionPicker from '../map-selection/MapPositionPicker.vue'
import M3CastFields from '../M3CastFields.vue'
import GmSpellFields from '../GmSpellFields.vue'
import type {GmSpellChoice} from '../../persistence/gm-spell-choice-schema'
import type {M3CastChoice} from '../../core/m3-spells'
import {computed,ref,watch} from 'vue'
import type {RoomView} from '../../online/protocol'
import type {SummonView} from '../../server/room-summons'
import type {SummonAction} from '../../persistence/summon-action-schema'
const props=defineProps<{view:RoomView;instance:SummonView;busy:boolean;picked?:{x:number;y:number;height:number}}>(),emit=defineEmits<{action:[SummonAction]}>()
const touchMaterial=ref(''),touchWeapon=ref(''),touchG=ref<GmSpellChoice>({}),touchM3=ref<M3CastChoice>({})
const operation=ref('command'),text=ref(''),note=ref(''),targetId=ref(''),riderId=ref(''),objectId=ref(''),x=ref(props.instance.position?.x??0),y=ref(props.instance.position?.y??0),height=ref(props.instance.position?.height??0),mode=ref<'walk'|'climb'|'swim'|'fly'>('walk'),familiarAction=ref<'pocket'|'return'|'end'|'senses'|'communicate'|'mimic'|'ink'|'help'|'jump'>('senses'),task=ref<'fetch'|'put'|'clean'|'mend'|'fold'|'light'|'serve'|'pour'|'wait'>('wait'),key=ref(''),castMode=ref('slot'),others=ref<string[]>([]),batchId=ref(''),containerId=ref(''),units=ref(1),phase=ref<'start'|'end'>('end'),restStart=ref(0)
const i=computed(()=>props.instance),tokens=computed(()=>props.view.scene?.tokens??[]),riders=computed(()=>tokens.value.filter(t=>props.view.self.role==='gm'||props.view.self.characterIds.includes(t.characterId??''))),touchChoices=computed(()=>props.view.summonTouchChoices?.filter(c=>c.sourceId===i.value.sourceId)??[]),options=computed(()=>!i.value.controlled?['mount','dismount']:i.value.state==='fading'?['dismount']:[
 ...(i.value.kind==='force'?['servant-task']:['command','move','attach']),...(i.value.spellId==='summon-fey'?['fey-step']:[]),...(i.value.spellId==='find-familiar'?['familiar','touch-cast','chain-attack']:[]),...(['find-steed','phantom-steed'].includes(i.value.spellId??'')?['mount','dismount']:[]),...(i.value.spellId==='phantom-steed'?['gear']:[]),...(i.value.spellId==='find-steed'?['steed-power']:[]),'carry','drop','task-complete',...(props.view.self.role==='gm'?['follow','phase',...(i.value.spellId==='find-steed'?['steed-rest']:[])]:[])
]),labels:Record<string,string>={'steed-rest':'GM确认坐骑实际长休',phase:'GM自由探索个人时序',gear:'魅影驹生成装备',command:'下达命令',move:'实际移动',attach:'加入当前战斗', 'fey-step':'妖精步伐',familiar:'魔宠能力','touch-cast':'传递触碰法术','chain-attack':'链契：牺牲主人攻击',mount:'上马',dismount:'下马','steed-power':'坐骑专能','servant-task':'仆役简单任务',carry:'携带实际物件',drop:'放下实际物件','task-complete':'任务完成',follow:'GM确认实际转场'}
watch(()=>props.picked,p=>{if(p){x.value=p.x;y.value=p.y;height.value=p.height;operation.value='move'}})
watch(key,k=>{castMode.value=touchChoices.value[Number(k)]?.modes[0]??'slot'})
watch(options,list=>{if(!list.includes(operation.value))operation.value=list[0]??'command'},{immediate:true})
const needPoint=computed(()=>['move','fey-step','steed-power','servant-task','dismount','follow','gear'].includes(operation.value)||operation.value==='familiar'&&['return','ink','jump'].includes(familiarAction.value))
function submit(){const base={instanceId:i.value.id,receipt:crypto.randomUUID(),note:note.value},to={x:x.value,y:y.value,height:height.value};let c:SummonAction
 if(operation.value==='touch-cast'&&key.value==='')return
 switch(operation.value){case 'command':c={operation:'command',sourceId:i.value.sourceId!,instanceIds:[i.value.id,...others.value],text:text.value||note.value,targetId:targetId.value||undefined,receipt:base.receipt,note:base.note};break
 case 'move':c={...base,operation:'move',to,mode:mode.value,supportId:objectId.value||undefined};break
 case 'fey-step':c={...base,operation:'fey-step',to,targetId:targetId.value||undefined};break
 case 'familiar':c={...base,operation:'familiar',action:familiarAction.value,to:needPoint.value?to:undefined,targetId:targetId.value||undefined,text:text.value};break
 case 'touch-cast':{const grant=touchChoices.value[Number(key.value)];if(!grant)return;c={...base,operation:'touch-cast',key:grant.key,mode:castMode.value,targetId:targetId.value,materialId:touchMaterial.value||undefined,weaponId:touchWeapon.value||undefined,choice:touchM3.value,gmChoice:touchG.value};break}
 case 'chain-attack':c={...base,operation:'chain-attack',targetId:targetId.value};break
 case 'mount':case 'dismount':c={...base,operation:'mount',riderId:riderId.value,mount:operation.value==='mount',to:operation.value==='dismount'?to:undefined};break
 case 'steed-power':c={...base,operation:'steed-power',targetId:targetId.value||undefined,to};break
 case 'servant-task':c={...base,operation:'servant-task',to,objectId:objectId.value||undefined,task:task.value,...(['pour','serve'].includes(task.value)?{supply:{batchId:batchId.value,containerId:containerId.value,units:units.value}}:{})};break
 case 'steed-rest':c={...base,operation:'steed-rest',startedHour:restStart.value};break
 case 'phase':c={...base,operation:'phase',phase:phase.value,targetId:targetId.value||undefined};break
 case 'gear':c={...base,operation:'gear',objectId:objectId.value,holderId:riderId.value||undefined,to:riderId.value?undefined:to};break
 case 'carry':case 'drop':c={...base,operation:'carry',objectId:objectId.value,take:operation.value==='carry'};break
 case 'follow':c={...base,operation:'follow',sceneId:props.view.scene!.id,to};break
 case 'task-complete':c={...base,operation:'task-complete'};break
 default:c={...base,operation:'attach'}
 }emit('action',c)}
</script>
<template><MapPositionPicker :scene-id="i.sceneId??view.scene?.id" :span="operation==='dismount'?tokens.find(t=>[t.id,t.characterId,t.npcId,t.actorId].includes(riderId||i.riderId||''))?.span??1:i.position?.span??1" :required="['ghost-eject','dismount'].includes(operation)" v-if="needPoint" :x="x" :y="y" :height="height" :disabled="busy" @select="p=>{x=p.x;y=p.y;height=p.height}" /><details v-if="instance.controlled||instance.rideable" class="summon-actions"><summary>{{ controlText('spatial.commandAbilities') }}</summary><div class="s-action-form"><label>{{ controlText('game.operation') }}<select v-model="operation"><option v-for="op in options" :key="op" :value="op">{{uiLabel(labels[op])}}</option></select></label>
 <label v-if="operation==='steed-rest'">{{ controlText('spatial.restStart') }}<input v-model.number="restStart" type="number" min="0" /><span>{{ controlText('spatial.restHint') }}</span></label>
 <label v-if="operation==='phase'">{{ controlText('spatial.explicitTiming') }}<select v-model="phase"><option value="start">{{ controlText('spatial.turnStart') }}</option><option value="end">{{ controlText('spatial.turnEnd') }}</option></select></label>
 <label v-if="operation==='familiar'">{{ controlText('spatial.familiarActions') }}<select v-model="familiarAction"><option value="senses">{{ controlText('spatial.familiarSenses') }}</option><option value="communicate">{{ controlText('spatial.telepathy') }}</option><option value="pocket">{{ controlText('spatial.dismissTemporary') }}</option><option value="return">{{ controlText('spatial.reappear') }}</option><option value="end">{{ controlText('spatial.dismissPermanent') }}</option><option value="help">{{ controlText('domain.help') }}</option><option value="mimic">{{ controlText('spatial.raven') }}</option><option value="ink">{{ controlText('spatial.octopus') }}</option><option value="jump">{{ controlText('spatial.catFrog') }}</option></select></label>
 <label v-if="operation==='command'||operation==='familiar'">{{ controlText('spatial.commandText') }}<input v-model="text" maxlength="1000" /></label>
 <label v-if="operation==='command'&&i.spellId==='animate-dead'">{{ controlText('spatial.undeadRecipients') }}<select v-model="others" multiple><option v-for="other in view.summons?.filter(n=>n.id!==i.id&&n.spellId==='animate-dead'&&n.controlled&&n.sourceId===i.sourceId)" :key="other.id" :value="other.id">{{localizedEntryName(other)}}</option></select></label>
 <label>{{ controlText('spatial.actualTarget') }}<MapFieldPicker kind="entity"><select v-model="targetId"><option value="">{{ controlText('spatial.noTarget') }}</option><option v-for="t in tokens" :key="t.id" :value="t.characterId??t.npcId??t.actorId??t.id">{{localizedEntryName(t)}}</option></select></MapFieldPicker></label>
 <template v-if="operation==='touch-cast'"><label>{{ controlText('spatial.touchSpell') }}<select v-model="key"><option value="">{{ controlText('spatial.chooseSpell') }}</option><option v-for="(g,n) in touchChoices" :key="g.key" :value="String(n)">{{localizedEntryName(g)}}</option></select></label><label>{{ controlText('spatial.castingMethod') }}<select v-model="castMode"><option v-for="m in touchChoices[Number(key)]?.modes??[]" :key="m" :value="m">{{m}}</option></select></label><M3CastFields :spell-id="touchChoices[Number(key)]?.spellId??''" v-model="touchM3" /><GmSpellFields :spell-id="touchChoices[Number(key)]?.spellId" v-model="touchG" :targets="tokens.map(t=>({id:t.characterId??t.npcId??t.actorId??t.id,name:t.name}))" /><label>{{ controlText('spatial.materialId') }}<input v-model="touchMaterial" /></label><label v-if="['magic-weapon','elemental-weapon'].includes(touchChoices[Number(key)]?.spellId??'')">{{ controlText('spatial.weaponId') }}<input v-model="touchWeapon" /></label></template>
 <label v-if="operation==='mount'||operation==='dismount'">{{ controlText('spatial.rider') }}<MapFieldPicker kind="entity"><select v-model="riderId"><option value="">{{ controlText('spatial.chooseRider') }}</option><option v-for="r in riders" :key="r.id" :value="r.characterId??r.npcId??r.actorId??r.id">{{localizedEntryName(r)}}</option></select></MapFieldPicker></label>
 <div v-if="needPoint" class="s-destination"><label>{{ controlText('game.landingX') }}<input v-model.number="x" type="number" min="0" :max="(view.scene?.grid.columns??80)-1" /></label><label>{{ controlText('game.landingY') }}<input v-model.number="y" type="number" min="0" :max="(view.scene?.grid.rows??80)-1" /></label><label>{{ controlText('game.height') }}<input v-model.number="height" type="number" /></label></div>
 <label v-if="operation==='move'">{{ controlText('game.movementMode') }}<select v-model="mode"><option value="walk">{{ controlText('game.walk') }}</option><option value="fly">{{ controlText('game.fly') }}</option><option value="swim">{{ controlText('game.swim') }}</option><option value="climb">{{ controlText('game.climb') }}</option></select></label>
 <label v-if="['move','carry','drop','servant-task'].includes(operation)">{{ controlText('spatial.objectSupport') }}<select v-model="objectId"><option value="">{{ controlText('spatial.chooseOptionalObject') }}</option><option v-for="o in view.scene?.spatialObjects" :key="o.id" :value="o.id">{{localizedEntryName(o)}}</option></select></label>
 <label v-if="operation==='servant-task'">{{ controlText('spatial.simpleTask') }}<select v-model="task"><option value="wait">{{ controlText('spatial.wait') }}</option><option value="fetch">{{ controlText('spatial.take') }}</option><option value="put">{{ controlText('spatial.putDown') }}</option><option value="clean">{{ controlText('spatial.clean') }}</option><option value="mend">{{ controlText('spatial.mend') }}</option><option value="fold">{{ controlText('spatial.fold') }}</option><option value="light">{{ controlText('spatial.igniteLight') }}</option><option value="serve">{{ controlText('spatial.serveFood') }}</option><option value="pour">{{ controlText('spatial.pourDrink') }}</option></select></label>
 <template v-if="operation==='gear'"><label>{{ controlText('spatial.createGear') }}<select v-model="objectId"><option value="">{{ controlText('spatial.chooseGear') }}</option><option v-for="g in instance.generatedGear?.filter(g=>g.enabled)" :key="g.id" :value="g.id">{{localizedEntryName(g)}}</option></select></label><label>{{ controlText('spatial.giveRider') }}<MapFieldPicker kind="entity"><select v-model="riderId"><option value="">{{ controlText('spatial.placeDestination') }}</option><option v-for="r in riders" :key="r.id" :value="r.characterId??r.npcId??r.actorId??r.id">{{localizedEntryName(r)}}</option></select></MapFieldPicker></label></template>
 <template v-if="operation==='servant-task'&&['serve','pour'].includes(task)"><label>{{ controlText('spatial.supplyBatch') }}<select v-model="batchId"><option value="">{{ controlText('spatial.chooseSupply') }}</option><option v-for="b in view.scene?.sceneEffects?.supplies?.batches" :key="b.id" :value="b.id">{{b.appearance}} · {{b.units}}</option></select></label><label>{{ controlText('spatial.receivingContainer') }}<select v-model="containerId"><option value="">{{ controlText('spatial.chooseContainer') }}</option><option v-for="c in view.scene?.sceneEffects?.supplies?.containers" :key="c.id" :value="c.id">{{localizedEntryName(c)}}</option></select></label><label>{{ controlText('spatial.ounces') }}<input v-model.number="units" type="number" min="1" /></label></template>
 <label>{{ controlText('spatial.operationBasis') }}<input v-model="note" maxlength="1000" /></label><p class="muted">{{ controlText('spatial.commandHint') }}</p><button type="button" :disabled="busy||!note.trim()" @click="submit">{{view.self.role==='gm'?controlText('expressionFour.executeCompanionOperation'):controlText('expressionFour.submitCompanionOperationForReview')}}</button>
 </div></details></template>
<style scoped>.s-action-form{display:grid;gap:.5rem;padding:.5rem 0}.s-action-form label{display:grid;gap:.25rem;min-width:0}.s-action-form input,.s-action-form select{width:100%;min-width:0}.s-destination{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.4rem}.s-action-form p{font-size:.85rem;margin:0}@media(max-width:500px){.s-destination{grid-template-columns:repeat(2,minmax(0,1fr))}.s-action-form button{min-height:44px}}</style>
